{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages the model to assign higher probabilities to candidate solutions with better advantages by weighting the log probabilities with advantage signals, aligned with the cost gap. Using pairwise comparisons, it promotes selecting options with superior advantage scores, thereby improving preference ranking based on cost efficiency. This approach directly leverages advantage signals to shape the policy towards preferred outcomes, penalizing less optimal choices.",
  "pseudocode": "loss = -mean_over_pairs(weight * (log_sigmoid(log_prob_w - log_prob_l)))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage",
    "link_family": "pairwise",
    "agg_family": "mean",
    "constraint_family": "cost"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\\n    log_prob_w = batch['log_prob_w']\\n    log_prob_l = batch['log_prob_l']\\n    weight = batch['weight']\\n    advantage_w = batch['advantage_w']\\n    advantage_l = batch['advantage_l']\\n    cost_gap = batch['cost_gap']\\n\\n    advantage_diff = advantage_w - advantage_l\\n    weighted_logits = weight * advantage_diff\\n    loss_terms = -ops.logsigmoid(log_prob_w - log_prob_l) * weighted_logits\\n    loss = ops.mean(loss_terms)\\n    return loss"
}

{
  "name": "loss_softplus_weighted_advantage_rank",
  "intuition": "Shift from margin-based pairwise loss to a paradigm prioritizing ranking quality by combining advantage-based scaling with a softplus link, aggregated via a weighted sum that emphasizes pairs with higher advantage difference magnitude, enforcing a smooth penalty on incorrect ranking order.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nlogit = (log_prob_w - log_prob_l) * adv_diff\nloss = mean(weight * softplus(-logit.abs()) * (adv_diff.abs()))",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "softplus",
    "agg_family": "weighted_sum",
    "constraint_family": "abs_scaled"
  },
  "operators_used": ["softplus", "abs", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    adv_diff = adv_w - adv_l\n    logit = (lpw - lpl) * adv_diff\n    term = ops.softplus(-ops.abs(logit)) * ops.abs(adv_diff)\n    weighted_term = weight * term\n    return weighted_term.mean()"
}

{
  "name": "loss_rankgap_tanh_advantage",
  "intuition": "Use the tanh of the advantage gap weighted by rank difference to enforce smooth ranking preferences, shifting from margin-based logsigmoid losses to a rank-based nonlinear transformation paradigm.",
  "pseudocode": "rank_diff = delta_rank.detach()\nadv_gap = advantage_gap\nscaled = tanh(scale * adv_gap)\nloss_per_pair = relu(-scaled * sign(rank_diff)) * weight\nloss = mean(loss_per_pair)",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_based",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "relu_nonnegative"
  },
  "operators_used": ["tanh", "relu", "sign", "mean", "mul", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_gap = batch['advantage_gap']\n    rank_diff = batch['delta_rank'].detach()\n    weight = batch.get('weight', None)\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    scaled = ops.tanh(ops.mul(scale, adv_gap))\n    # Sign rank_diff: +1 means w ranked higher, -1 means l ranked higher\n    sign_rd = ops.sign(rank_diff)\n    # Loss penalizes if scaled adv_gap disagrees with rank order (negative product)\n    disagreement = ops.relu(ops.neg(ops.mul(scaled, sign_rd)))\n    if weight is not None:\n        disagreement = ops.mul(disagreement, weight)\n    return ops.mean(disagreement)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages selecting pairs based on advantage signals while penalizing high cost gaps. It promotes policies with higher advantage and lower cost gap, aligning with the goal of optimizing quality versus cost trade-offs.",
  "pseudocode": "loss = mean over pairs of [logsigmoid(advantage_w - advantage_l) - logsigmoid(cost_gap)]",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "advantage",
    "link_family": "logits",
    "agg_family": "mean",
    "constraint_family": "cost-based",
    "other_hparams": "alpha=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\\n    advantage_w = batch[\"advantage_w\"]\\n    advantage_l = batch[\"advantage_l\"]\\n    cost_gap = batch[\"cost_gap\"]\\n    log_prob_w = batch[\"log_prob_w\"]\\n    log_prob_l = batch[\"log_prob_l\"]\\n    weight = batch[\"weight\"]\\n    advantage_diff = advantage_w - advantage_l\\n    cost_penalty = -cost_gap\\n    loss_term = logsigmoid(advantage_diff) + logsigmoid(cost_penalty)\\n    weighted_loss = loss_term * weight\\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "To stabilize and simplify the original loss combining advantage and cost_gap signals, we clamp cost_gap to a reasonable range before negation to avoid numerical instabilities from large cost values. We replace the sum of two logsigmoid terms with a single logsigmoid on the advantage difference minus a clamped cost penalty, ensuring the loss remains numerically stable and interpretable as a preference signal adjusted by the cost. This avoids invalid expectations from separate logsigmoid terms that may conflict or saturate, while preserving the pairwise advantage comparison and penalizing large cost gaps.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_w",
      "advantage_l",
      "cost_gap"
    ]
  },
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch[\"advantage_w\"]\n    advantage_l = batch[\"advantage_l\"]\n    cost_gap = batch[\"cost_gap\"]\n    log_prob_w = batch[\"log_prob_w\"]\n    log_prob_l = batch[\"log_prob_l\"]\n    weight = batch[\"weight\"]\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    # Clamp cost_gap to [-5, 0] to stabilize and avoid extreme penalties\n    cost_clamped = ops.clamp(cost_gap, min=-5.0, max=0.0)\n    cost_penalty = ops.neg(cost_clamped)\n    # Combine advantage difference and cost penalty into a single preference logit\n    preference_logit = ops.sub(advantage_diff, cost_penalty)\n    loss_term = ops.logsigmoid(preference_logit)\n    weighted_loss = ops.mul(loss_term, weight)\n    return ops.mean(weighted_loss)"
}

{
  "name": "pairwise_advantage_loss",
  "intuition": "This loss encourages selecting options with higher advantage scores by penalizing pairs where the less advantageous option is chosen. Using advantage signals aligns directly with preference optimization, as higher advantage indicates preferred outcomes. The pairwise formulation promotes consistency and smoothness in preference gradients, helping the RL agent improve decision quality effectively.",
  "pseudocode": "loss = mean over pairs of (logsigmoid(advantage_w - advantage_l) * weight)",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "margin"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    adv_w = batch[\"advantage_w\"]\n    adv_l = batch[\"advantage_l\"]\n    weights = batch[\"weight\"]\n    advantage_diff = adv_w - adv_l\n    loss_per_pair = ops.logsigmoid(advantage_diff) * weights\n    loss = ops.mean(loss_per_pair)\n    return loss"
}

{
  "name": "combined_pairwise_loss_stabilized",
  "intuition": "The loss is simplified by removing the logsigmoid term which involves potential numerical instability and is less directly tied to margin semantics. Instead, it focuses on the stable tanh-transformed advantage gap with ReLU clipping plus a margin based on log_prob differences, both weighted and combined with a mean reduction. Clamping the advantage_gap before tanh adds numeric stability. This retains expressiveness while eliminating unstable logsigmoid and difference of advantages that might cause preference semantic issues.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ],
    "returns": "scalar"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(lpw))\n    adv_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', 1.0))\n    beta = float(extra.get('beta', 1.0))\n    # Clamp advantage gap to avoid extreme values causing instability\n    adv_gap_clamped = ops.clamp(adv_gap, -10.0, 10.0)\n    margin = ops.tanh(alpha * adv_gap_clamped)\n    margin_clipped = ops.relu(margin)\n    diff = beta * (lpl - lpw) + margin_clipped\n    loss = ops.relu(diff) * weight\n    return loss.mean()"
}

